import * as vscode from 'vscode'
import type {DefinitionNode} from '../configuration-model.js'
import type {ProjectionDefinition} from '../projections/definitions.js'
import {buildRow, type BuildState} from '../renderer-build-model.js'

/**
 * The parts' product icons (`contributes.icons`, a font generated by tools/scripts/product-icons.mjs from brand/parts): a dot
 * is the extraction, which the extractor's strokes converge on, the comparator divides from another, and the
 * renderer's strokes leave.
 */
export const partIcons = {
  extractor: 'projections-extractor',
  comparator: 'projections-comparator',
  renderer: 'projections-renderer',
} as const

/** A part's value as a short fact: a file's name, a bundle's package (`cards/dist`), else the value verbatim. */
function partFact(node: DefinitionNode): string {
  if (node.file) return node.file.split('/').at(-1) ?? node.file
  const value = node.value ?? ''
  if (node.kind === 'renderer' && value.includes('/')) return value.replace(/\/+$/, '').split('/').slice(-2).join('/')
  return value
}

/** What a row needs beyond its node: where its files are, its projection's definition and its renderer's build. */
export interface ItemContext {
  folder: vscode.WorkspaceFolder
  projection: string
  definition: ProjectionDefinition | undefined
  build: BuildState | undefined
}

const at = (context: ItemContext, path: string) => vscode.Uri.joinPath(context.folder.uri, ...path.replace(/^\.\//, '').split('/'))
const open = (context: ItemContext, path: string): vscode.Command => ({
  title: 'Open File',
  command: 'vscode.open',
  arguments: [at(context, path)],
})

/** A file (the definition, a tests file, a renderer's source): its file icon and name, as the Explorer shows it. */
function fileItem(item: vscode.TreeItem, node: DefinitionNode, context: ItemContext) {
  item.resourceUri = at(context, node.file!)
  item.iconPath = vscode.ThemeIcon.File
  item.tooltip = new vscode.MarkdownString(
    [
      `\`${node.file}\``,
      '',
      node.kind === 'definition'
        ? 'The definition: its extractor, comparator and renderer.'
        : node.kind === 'tests'
          ? "The comparator's tests: run them in the Testing view, or from the gutter."
          : "The custom renderer's source.",
    ].join('\n'),
  )
  item.command = open(context, node.file!)
}

function scenariosItem(item: vscode.TreeItem, node: DefinitionNode, context: ItemContext) {
  item.description = node.count !== undefined ? `${node.count} scenario${node.count === 1 ? '' : 's'}` : ''
  item.iconPath = new vscode.ThemeIcon('beaker')
  item.tooltip = new vscode.MarkdownString(
    [`\`${node.file}\``, '', "Click to open the renderer's scenarios in the renderer and comparator workbench."].join('\n'),
  )
  item.command = {title: 'Open Renderer Scenarios', command: 'projections.openScenarios', arguments: [at(context, node.value ?? '.')]}
}

function environmentItem(item: vscode.TreeItem, node: DefinitionNode, context: ItemContext) {
  item.description = node.value ?? ''
  item.iconPath = new vscode.ThemeIcon('server-environment')
  item.tooltip = new vscode.MarkdownString(
    [`\`${node.file}\``, '', 'The repository environment the extractors run in (Projections: Prepare Environment).'].join('\n'),
  )
  item.command = open(context, node.file!)
}

/** An extractor, comparator or renderer: its value, its build when the extension builds it, and where a click goes. */
function partItem(item: vscode.TreeItem, node: DefinitionNode & {kind: keyof typeof partIcons}, context: ItemContext) {
  const part = node.kind
  item.description = partFact(node)
  item.iconPath = new vscode.ThemeIcon(partIcons[part])
  const {definition} = context
  const bundle =
    part === 'renderer' && !node.file && !node.docs && definition && typeof definition.renderer !== 'string'
      ? at(context, definition.renderer.bundle)
      : undefined
  // A custom renderer the extension builds on save: building, built or failed (its error in the tooltip).
  const state = part === 'renderer' ? context.build : undefined
  const build = state && buildRow(state)
  if (build) {
    item.description = `${item.description} · ${build.description}`
    if (build.icon) item.iconPath = new vscode.ThemeIcon(build.icon)
  }
  item.tooltip = new vscode.MarkdownString(
    [
      `**${node.label}:** \`${node.value ?? ''}\``,
      '',
      node.file
        ? `Click to open \`${node.file}\`.`
        : bundle
          ? 'Click to reveal its bundle in the Explorer.'
          : node.docs
            ? 'A built-in: click to read its documentation here in VS Code.'
            : 'Click to open its entry in the definition.',
      ...(part === 'comparator'
        ? ['', 'Configure… opens its entry in the definition (the default comparator: configure it or choose a comparator file).']
        : []),
      ...(part === 'extractor' ? ['', 'Show Extraction Output writes the shown extractions to the Projections output.'] : []),
      ...(build ? ['', build.detail] : []),
    ].join('\n'),
  )
  item.command = node.file
    ? open(context, node.file)
    : bundle
      ? {
          title: 'Reveal in Explorer',
          command: 'revealInExplorer',
          arguments: [bundle],
        }
      : node.docs
        ? {
            title: 'Open Documentation',
            command: 'projections.openDocumentation',
            arguments: [node.docs],
          }
        : {
            title: 'Open Definition Entry',
            command: 'projections.openPart',
            arguments: [context.folder.uri, context.projection, part],
          }
}

/** A row of the Definition view: a file, the renderer's scenarios, the environment, or a part. */
export function definitionItem(node: DefinitionNode, context: ItemContext, id: string): vscode.TreeItem {
  const item = new vscode.TreeItem(
    node.label,
    node.children.length ? vscode.TreeItemCollapsibleState.Expanded : vscode.TreeItemCollapsibleState.None,
  )
  item.id = id
  // A built-in's row says it has docs, for Open Documentation on GitHub.
  item.contextValue = `definition-${node.kind}${node.docs ? ' docs' : ''}`
  switch (node.kind) {
    case 'definition':
    case 'tests':
    case 'source':
      fileItem(item, node, context)
      break
    case 'scenarios':
      scenariosItem(item, node, context)
      break
    case 'environment':
      environmentItem(item, node, context)
      break
    default:
      partItem(item, {...node, kind: node.kind}, context)
  }
  return item
}
